        "import matplotlib.pyplot as plt\n",
        "import numpy as np\n",
        "\n",
        "angles = np.linspace(0, 2 * np.pi, 10)\n",
        "radii = np.abs(np.sin(angles))\n",
        "\n",
        "plt.polar(angles, radii)\n",
        "plt.title('Polar Plot Example')\n",
        "plt.show()"
